import hashlib, subprocess, itertools

target=bytes.fromhex("1acef345a48e5ecf91ce0becb6c466df")
pw=b"pw"

def aes_ecb(key, block):
    # key len 16,24,32 determines aes
    bits=len(key)*8
    r=subprocess.run(["openssl","enc",f"-aes-{bits}-ecb","-K",key.hex(),"-nopad"], input=block, capture_output=True)
    if r.returncode!=0:
        #print(r.stderr)
        return None
    return r.stdout

keys={}
def addk(name, b):
    if len(b) in (16,24,32): keys[name]=b
    # also trunc/pad variants added separately

hashes={
 "md5": hashlib.md5(pw).digest(),
 "sha1": hashlib.sha1(pw).digest(),
 "sha256": hashlib.sha256(pw).digest(),
 "sha512": hashlib.sha512(pw).digest(),
 "sha224": hashlib.sha224(pw).digest(),
 "sha384": hashlib.sha384(pw).digest(),
}
for n,h in hashes.items():
    for l in (16,24,32):
        if len(h)>=l: keys[f"{n}[:{l}]"]=h[:l]
        # hex digest as bytes
    hexd=h.hex().encode()
    for l in (16,24,32):
        if len(hexd)>=l: keys[f"{n}.hex[:{l}]"]=hexd[:l]
# password padded
for l in (16,24,32):
    keys[f"pw zeropad{l}"]=pw.ljust(l,b"\x00")
    keys[f"pw spacepad{l}"]=pw.ljust(l,b" ")
    keys[f"pw repeat{l}"]=(pw*((l // len(pw))+1))[:l]
    keys[f"pw PKCS?pad{l}"]=pw.ljust(l, bytes([l-len(pw)])) if l>len(pw) else pw[:l]
# EVP_BytesToKey MD5 no salt, 1 iteration (?) generate 48 bytes
def evp(password, key_len, iv_len, salt=b"", count=1, hash_name="md5"):
    out=b""; prev=b""
    while len(out)<key_len+iv_len:
        d=prev+password+salt
        for i in range(count):
            d=hashlib.new(hash_name, d).digest()
        prev=d; out+=d
    return out[:key_len], out[key_len:key_len+iv_len]
for kl in (16,24,32):
    for salt in [b"", b"\x00"*8]:
        for cnt in [1,5]:
            for hn in ["md5","sha1","sha256"]:
                k,iv=evp(pw,kl,16,salt,cnt,hn)
                keys[f"evp{hn} kl{kl} salt{len(salt)} cnt{cnt} [IVspecial={iv.hex()}]"]=k  # we will also try its iv below separately?

ivs={}
ivs["zero"]=b"\x00"*16
ivs["space"]=b" "*16
ivs["zerochar"]=b"0"*16
ivs["pw zeropad"]=pw.ljust(16,b"\x00")
ivs["pw spacepad"]=pw.ljust(16,b" ")
ivs["pw repeat"]=(pw*8)[:16]
for n,h in hashes.items():
    if len(h)>=16: ivs[n]=h[:16]
    if len(h)>=32: ivs[n+" second16"]=h[16:32]
    hexd=h.hex().encode()
    ivs[n+".hex"]=hexd[:16]
# evp ivs
evp_ivs={}
for kl in (16,24,32):
    for hn in ["md5","sha1","sha256"]:
        k,iv=evp(pw,kl,16,b"",1,hn)
        evp_ivs[f"evp{hn}kl{kl}"]=iv
        # directly test this pair
        out=aes_ecb(k,iv)
        if out==target:
            print("FOUND EVP", hn, kl, k.hex(), iv.hex())
ivs.update(evp_ivs)
# maybe IV is like 16 bytes of something constant like "initializationv" etc later

found=False
for kn,k in keys.items():
    for ivn,iv in ivs.items():
        out=aes_ecb(k,iv)
        if out==target:
            print("FOUND",kn,k.hex(),ivn,iv.hex()); found=True
print("done found?",found, "tried",len(keys),len(ivs))
