import re
ansi_re=re.compile(r'\x1b\[([0-9;]*)m')
def parse_rows(esc_text):
    rows=[]
    for line in esc_text.splitlines():
        cells=[]; attrs=set(); fg=None; bg=None
        i=0
        while i<len(line):
            m=ansi_re.match(line,i)
            if m:
                codes=[int(x) if x else 0 for x in m.group(1).split(';')] if m.group(1)!='' else [0]
                j=0
                while j<len(codes):
                    c=codes[j]
                    if c==0: attrs=set(); fg=None; bg=None
                    elif c in (1,2,3,4,5,6,7,8,9): attrs.add(c)
                    elif c==22: attrs.discard(1); attrs.discard(2)
                    elif c==23: attrs.discard(3)
                    elif c==24: attrs.discard(4)
                    elif c==25: attrs.discard(5); attrs.discard(6)
                    elif c==27: attrs.discard(7)
                    elif c==28: attrs.discard(8)
                    elif c==29: attrs.discard(9)
                    elif 30<=c<=37 or 90<=c<=97: fg=c
                    elif c==39: fg=None
                    elif 40<=c<=47 or 100<=c<=107: bg=c
                    elif c==49: bg=None
                    elif c==38:
                        # 38;5;n or 38;2;r;g;b
                        if j+2<len(codes) and codes[j+1]==5: fg=('256',codes[j+2]); j+=2
                        elif j+4<len(codes) and codes[j+1]==2: fg=('rgb',tuple(codes[j+2:j+5])); j+=4
                    elif c==48:
                        if j+2<len(codes) and codes[j+1]==5: bg=('256',codes[j+2]); j+=2
                        elif j+4<len(codes) and codes[j+1]==2: bg=('rgb',tuple(codes[j+2:j+5])); j+=4
                    j+=1
                i=m.end(); continue
            ch=line[i]
            # wide? tmux output characters are per cell mostly.
            cells.append((ch,tuple(sorted(attrs)),fg,bg))
            i+=1
        rows.append(cells)
    return rows
def cell(rows,x,y):
    if y<len(rows) and x<len(rows[y]): return rows[y][x]
    return None
def find_text(rows, text):
    locs=[]
    for y,row in enumerate(rows):
        s=''.join(c[0] for c in row)
        start=0
        while True:
            idx=s.find(text,start)
            if idx<0: break
            locs.append((idx,y)); start=idx+1
    return locs
