def fs_str(p):
    return os.fsdecode(p)

def is_abs_path(p):
    return p.startswith('/')

def fs_join(a, b):
    a = fs_str(a); b = fs_str(b)
    if b.startswith('/'):
        return b
    if a == '':
        return b
    if a.endswith('/'):
        return a + b
    return a + '/' + b

def fs_exists(p):
