def fs_error_msg(action, err_no, path, path2=None):
    try:
        text = os.strerror(err_no)
    except Exception:
        text = str(err_no)
    msg = f"filesystem error: {action}: {text} [{path}]"
    if path2 is not None:
        msg += f" [{path2}]"
    return msg

def cpp_create_directories(path):
    # Emulate libstdc++ std::filesystem::create_directories
    path = fs_str(path)
    # Walk prefixes.  We use the lexical form but perform real mkdir calls.
    if path == '':
        # create_directories("") in libstdc++ raises? approximate as no-op/missing
        raise AppError(fs_error_msg('cannot create directories', errno.ENOENT, path))
    # Determine prefixes, handling root and .
    prefixes = []
    if path.startswith('/'):
        cur = '/'
        rest = path[1:]
        parts = rest.split('/') if rest != '' else []
    else:
        cur = ''
        parts = path.split('/')
    for part in parts:
        if part == '' or part == '.':
            continue
        if cur == '' or cur == '/':
            cur = (cur + part) if cur == '/' else part
        else:
            cur = cur + '/' + part
        prefixes.append(cur)
    if not prefixes:
        return
    for pref in prefixes:
        try:
            st = os.stat(pref)  # follows symlinks
            import stat as _stat
            if not _stat.S_ISDIR(st.st_mode):
                raise AppError(fs_error_msg('cannot create directories', errno.ENOTDIR, path))
            continue
        except FileNotFoundError:
            pass
        except NotADirectoryError:
            raise AppError(fs_error_msg('cannot create directories', errno.ENOTDIR, path))
        except PermissionError:
            raise AppError(fs_error_msg('cannot create directories', errno.EACCES, path))
        except OSError as e:
            # symlink loop etc.
            raise AppError(fs_error_msg('cannot create directories', e.errno or errno.EIO, path))
        try:
            os.mkdir(pref)
        except FileExistsError:
            # Could be a dangling symlink or file
            try:
                st = os.stat(pref)
                import stat as _stat
                if not _stat.S_ISDIR(st.st_mode):
                    raise AppError(fs_error_msg('cannot create directories', errno.ENOTDIR, path))
            except FileNotFoundError:
                # dangling symlink
                raise AppError(fs_error_msg('cannot create directories', errno.EEXIST, path))
            except AppError:
                raise
            except OSError as e:
                raise AppError(fs_error_msg('cannot create directories', e.errno or errno.EEXIST, path))
        except OSError as e:
            en = e.errno or errno.EIO
            # mkdir of a path whose component is a file gives ENOTDIR already
            raise AppError(fs_error_msg('cannot create directories', en, path))

def dir_entries(path):
    # returns list of names in os.scandir order; raise AppError like directory_iterator
    try:
