def expand_tilde_bug(path):
    p = fs_str(path)
    if not p.startswith('~'):
        return p
    if len(p) < 2:
        raise AppError('basic_string::substr: __pos (which is 2) > this->size() (which is 1)')
    suffix = p[2:]
