# ---------------- dates (proleptic Gregorian, Howard Hinnant algorithms) ----------------

def days_from_civil(y, m, d):
    # m 1..12 normally, but supports arbitrary ints in a C++ chrono-like way for
    # month values stored in unsigned char after event parsing (0..255) etc.
    # Normalize month first into 1..12 with year adjustment for the arithmetic.
    # For day overflow, the algorithm below naturally carries via the formula
    # if we treat (y,m) as a year/month pair and add d-1 days.
    # First normalize m:
    # Python floor division matches mathematical month normalization.
    y_adj = y + (m - 1) // 12
    m_norm = (m - 1) % 12 + 1
    # days_from_civil for first of month
    yy = y_adj - (1 if m_norm <= 2 else 0)
    era = yy // 400 if yy >= 0 else (yy - 399) // 400
    yoe = yy - era * 400
    mp = (m_norm + 9) % 12
    doy = (153 * mp + 2) // 5  # day of year for day=1
    doe = yoe * 365 + yoe // 4 - yoe // 100 + doy
    days_first = era * 146097 + doe - 719468
    return days_first + (d - 1)

def civil_from_days(z):
    z += 719468
    era = z // 146097 if z >= 0 else (z - 146096) // 146097
    doe = z - era * 146097
    yoe = (doe - doe // 1460 + doe // 36524 - doe // 146096) // 365
    y = yoe + era * 400
    doy = doe - (365 * yoe + yoe // 4 - yoe // 100)
    mp = (5 * doy + 2) // 153
    d = doy - (153 * mp + 2) // 5 + 1
    m = mp + 3 if mp < 10 else mp - 9
    y += 1 if m <= 2 else 0
    return (y, m, d)

def is_leap(y):
    return y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)

def days_in_month(y, m):
    if m == 2:
        return 29 if is_leap(y) else 28
    return (31,28,31,30,31,30,31,31,30,31,30,31)[m-1]

@dataclass(frozen=True)
class Date:
    y: int
    m: int
    d: int
    def ordinal(self):
        return days_from_civil(self.y, self.m, self.d)
    @staticmethod
    def from_ordinal(z):
        y,m,d = civil_from_days(z)
        return Date(y,m,d)
    def add_days(self, n):
        return Date.from_ordinal(self.ordinal() + n)
    def add_years(self, n):
        # chrono-like: preserve month/day, then normalize via ordinal (Feb29 -> Mar1)
        return Date.from_ordinal(days_from_civil(self.y + n, self.m, self.d))
    def weekday(self):
        # Monday=0. 1970-01-01 (ordinal 0) was Thursday (=3)
        return (self.ordinal() + 3) % 7
    def __lt__(self, other):
        return self.ordinal() < other.ordinal()
    def __le__(self, other):
        return self.ordinal() <= other.ordinal()

def today_local():
