            else: out.append(str(y))
        elif spec == 'y': out.append(f"{dt.y % 100:02d}")
        elif spec == 'C': out.append(f"{dt.y // 100:02d}")
        elif spec == 'm': out.append(f"{dt.m:02d}")
        elif spec == 'd': out.append(f"{dt.d:02d}")
        elif spec == 'e': out.append(f"{dt.d:2d}")
        elif spec == 'H': out.append("00")
        elif spec == 'I': out.append("12")
        elif spec == 'M': out.append("00")
        elif spec == 'S': out.append("00")
        elif spec == 'p': out.append("AM")
        elif spec == 'P': out.append("am")
        elif spec == 'j': out.append(f"{yday_zero+1:03d}")
        elif spec == 'B': out.append(MONTH_NAMES[dt.m-1])
        elif spec == 'b' or spec == 'h': out.append(MONTH_ABBR[dt.m-1])
        elif spec == 'A': out.append(WDAY_NAMES[wday_mon])
        elif spec == 'a': out.append(WDAY_ABBR[wday_mon])
        elif spec == 'w': out.append(str(wday_sun))
        elif spec == 'u': out.append(str(wday_mon+1))
        elif spec == 'F': out.append(f"{dt.y:04d}-{dt.m:02d}-{dt.d:02d}" if 0 <= dt.y <= 9999 else f"{dt.y}-{dt.m:02d}-{dt.d:02d}")
        elif spec == 'D': out.append(f"{dt.m:02d}/{dt.d:02d}/{dt.y%100:02d}")
        elif spec == 'x': out.append(f"{dt.m:02d}/{dt.d:02d}/{dt.y%100:02d}")
        elif spec == 'X': out.append("00:00:00")
        elif spec == 'T': out.append("00:00:00")
        elif spec == 'R': out.append("00:00")
        elif spec == 'r': out.append("12:00:00 AM")
        elif spec == 'c': out.append(f"{WDAY_ABBR[wday_mon]} {MONTH_ABBR[dt.m-1]} {dt.d:2d} 00:00:00 {dt.y}")
        elif spec == 'G':
            # ISO year: year of Thursday of this week
            iso = dt.add_days(3 - wday_mon)
            out.append(f"{iso.y:04d}")
        elif spec == 'g':
            iso = dt.add_days(3 - wday_mon)
            out.append(f"{iso.y % 100:02d}")
        elif spec == 'V':
            # ISO week
            # Thursday based
            th = dt.add_days(3 - wday_mon)
            jan1 = Date(th.y,1,1)
            # first Thursday
            # week = days since Jan1 Thursday-aligned /7 +1
            week = (th.ordinal() - jan1.ordinal()) // 7 + 1
            out.append(f"{week:02d}")
        elif spec == 'U':
            # Sunday as first day
            w = (yday_zero - wday_sun + 7) // 7
            out.append(f"{w:02d}")
        elif spec == 'W':
            w = (yday_zero - wday_mon + 7) // 7
            out.append(f"{w:02d}")
        elif spec == 'z': out.append(time.strftime('%z'))
        elif spec == 'Z': out.append(time.strftime('%Z'))
        elif spec == 's': out.append(str(int(time.mktime((dt.y,dt.m,dt.d,0,0,0,0,0,-1))) if 1 <= dt.y <= 9999 else str(dt.ordinal()*86400)))
        elif spec == 'n': out.append("\n")
        elif spec == 't': out.append("\t")
        else:
            # Unknown specifier: libstdc++ strftime leaves "%X" as is (observed via get_time/put_time behaviour)
            out.append('%' + spec)
    return ''.join(out)

# get_time emulation (libstdc++-like) for filename parsing.
# Returns (success, tm_dict, rest) where tm_dict has year/mon/mday/hour/min/sec/yday/wday if parsed.
class _ParseFail(Exception):
    pass

def _is_digit(ch):
    return '0' <= ch <= '9'

def parse_with_format(inp, fmt):
    # Returns None on failure, or dict on success per rules observed:
    # - leading whitespace in input is skipped (stream sentry)
    # - literals (except whitespace) must match case-insensitively for letters
    # - whitespace in format matches zero or more whitespace in input (strftime convention)
    # - numeric directives read up to a max width with optional sign for some; range-checked
    # - if EOF occurs while reading a numeric directive after >=1 digit, parsing ends successfully (truncated)
    # - leftover (up to newline) must be empty
    s = inp
    pos = 0
    n = len(s)
    # sentry skipws
    while pos < n and s[pos] in ' \t\n\r\v\f':
        pos += 1
    tm = {'year': None, 'mon': None, 'mday': None, 'hour': None, 'min': None, 'sec': None, 'yday': None, 'wday_sun': None}
    fi = 0
    truncated_success = False
    # Map month names for %b/%B
    def read_number(maxw, minv, maxv, allow_sign=False):
        nonlocal pos
        start = pos
        # libstdc++ numeric parsing: may skip? It doesn't skip spaces mid-format (tests showed)
        sign = 1
        if allow_sign and pos < n and s[pos] in '+-':
            if s[pos] == '-': sign = -1
            pos += 1
        digits = 0
        val = 0
        width_used = (pos - start)
        while pos < n and _is_digit(s[pos]) and (digits + width_used) < maxw:
            val = val * 10 + (ord(s[pos]) - 48)
            pos += 1; digits += 1
        if digits == 0:
            raise _ParseFail()
        val *= sign
        if val < minv or val > maxv:
            raise _ParseFail()
        if pos >= n:
            # EOF after digits -> truncated success marker
            raise _Truncated(val)
        return val
    class _Truncated(Exception):
        def __init__(self, val): self.val = val
    # Need to handle _Truncated per-directive assignment; wrap read in helper
    def read_num_assign(key, maxw, minv, maxv, transform=None, allow_sign=False):
        nonlocal truncated_success
        try:
            v = read_number(maxw, minv, maxv, allow_sign=allow_sign)
        except _Truncated as t:
            v = t.val
            if transform: v = transform(v)
            tm[key] = v
            truncated_success = True
            raise _Truncated(v)
        if transform: v = transform(v)
        tm[key] = v
        return v
    try:
        while fi < len(fmt):
            if truncated_success:
                break
            fc = fmt[fi]
            if fc == '%':
                if fi + 1 >= len(fmt):
                    # trailing % treated as literal '%'?
                    if pos < n and s[pos] == '%':
                        pos += 1; fi += 1; continue
                    raise _ParseFail()
                spec = fmt[fi+1]; fi += 2
                if spec in 'EO' and fi < len(fmt):
                    spec = fmt[fi]; fi += 1
                if spec == '%':
                    if pos >= n or s[pos] != '%': raise _ParseFail()
                    pos += 1
                elif spec == 'Y':
                    read_num_assign('year', 4, -999999, 999999, allow_sign=True)
                elif spec == 'y':
                    # 00-99, pivot: 69-99 -> 19xx, 00-68 -> 20xx (libstdc++ / POSIX)
                    def tr(v): return 1900+v if v >= 69 else 2000+v
                    read_num_assign('year', 2, 0, 99, transform=tr)
                elif spec == 'C':
                    # century: store for combining with %y - approximate: set year = v*100 (if %y later it will overwrite; uncommon)
                    try:
                        v = read_number(2, -99, 99, allow_sign=True)
                    except _Truncated as t:
                        tm['year'] = t.val*100; truncated_success=True; break
                    tm['year'] = v*100
                elif spec == 'm':
                    read_num_assign('mon', 2, 1, 12)
                elif spec == 'd' or spec == 'e':
                    # %e may have leading space
                    if spec == 'e':
                        while pos < n and s[pos] == ' ': pos += 1
                    read_num_assign('mday', 2, 1, 31)
                elif spec == 'H' or spec == 'k':
                    if spec == 'k':
                        while pos < n and s[pos] == ' ': pos += 1
                    read_num_assign('hour', 2, 0, 23)
                elif spec == 'I' or spec == 'l':
                    if spec == 'l':
                        while pos < n and s[pos] == ' ': pos += 1
                    read_num_assign('hour', 2, 1, 12)
                elif spec == 'M':
                    read_num_assign('min', 2, 0, 59)
                elif spec == 'S':
                    read_num_assign('sec', 2, 0, 60)
                elif spec == 'j':
                    read_num_assign('yday', 3, 1, 366)
                elif spec == 'w':
                    read_num_assign('wday_sun', 1, 0, 6)
                elif spec == 'u':
                    read_num_assign('wday_sun', 1, 1, 7, transform=lambda v: v % 7)
                elif spec == 'U' or spec == 'W' or spec == 'V':
                    # week number ignored
                    try: read_number(2, 0, 53)
                    except _Truncated: truncated_success=True; break
                elif spec == 'G':
                    read_num_assign('year', 4, -999999, 999999, allow_sign=True)
                elif spec == 'g':
                    try: read_number(2, 0, 99)
                    except _Truncated: truncated_success=True; break
                elif spec in ('b','B','h'):
                    # month name case-insensitive; match longest
                    rest = s[pos:].lower()
                    matched = None
                    names = [(MONTH_NAMES[i].lower(), i+1) for i in range(12)] + [(MONTH_ABBR[i].lower(), i+1) for i in range(12)]
                    names.sort(key=lambda x: -len(x[0]))
                    for nm, mv in names:
                        if rest.startswith(nm):
                            matched = (nm, mv); break
                    if not matched: raise _ParseFail()
                    pos += len(matched[0]); tm['mon'] = matched[1]
                    if pos >= n: truncated_success=True; break
                elif spec in ('a','A'):
                    rest = s[pos:].lower(); matched=None
                    names=[(WDAY_NAMES[i].lower(), i) for i in range(7)]+[(WDAY_ABBR[i].lower(), i) for i in range(7)]
                    names.sort(key=lambda x:-len(x[0]))
                    for nm,mv in names:
                        if rest.startswith(nm): matched=(nm,mv); break
                    if not matched: raise _ParseFail()
                    pos += len(matched[0]); tm['wday_sun'] = (matched[1]+1)%7
                    if pos >= n: truncated_success=True; break
                elif spec in ('p','P'):
                    rest=s[pos:].lower()
                    if rest.startswith('am'): pos+=2
                    elif rest.startswith('pm'): pos+=2
                    else: raise _ParseFail()
                    if pos>=n: truncated_success=True; break
                elif spec == 'F':
                    # %Y-%m-%d : emulate by recursive handling manually using sub-format
                    sub = parse_with_format(s[pos:], "%Y-%m-%d")
                    if sub is None: raise _ParseFail()
                    # We cannot know consumed length from this helper; approximate using formatted length logic is fragile.
                    # Instead, parse inline:
                    raise _ParseFail()
                elif spec == 'D':
                    raise _ParseFail()
                elif spec == 'z' or spec == 'Z':
                    # Consume a timezone token: [+/-]dddd or name - approximate: consume up to non matching next literal
                    raise _ParseFail()
                elif spec == 'n' or spec == 't':
                    while pos < n and s[pos] in ' \t\n\r\v\f': pos += 1
                    if pos>=n: truncated_success=False
                elif spec == 's':
                    # seconds since epoch
                    try:
                        v=read_number(20, -10**18, 10**18, allow_sign=True)
                        y,m,d=civil_from_days(v//86400)
                        tm['year']=y; tm['mon']=m; tm['mday']=d
                    except _Truncated as t:
                        v=t.val; y,m,d=civil_from_days(v//86400); tm['year']=y; tm['mon']=m; tm['mday']=d; truncated_success=True; break
                else:
                    # Unknown directive: libstdc++ get_time sets failbit
                    raise _ParseFail()
            elif fc in ' \t\n\r\v\f':
                # whitespace in format: skip any whitespace in input (including none?)
                while pos < n and s[pos] in ' \t\n\r\v\f': pos += 1
                fi += 1
            else:
                if pos >= n: raise _ParseFail()
                # literal match, case-insensitive for ASCII letters
                if s[pos].lower() != fc.lower(): raise _ParseFail()
                pos += 1; fi += 1
    except _Truncated:
        truncated_success = True
    except _ParseFail:
        return None
    # leftover check: getline rest must be empty (up to \n)
    rest = s[pos:]
    nl = rest.find('\n')
    line_rest = rest if nl < 0 else rest[:nl]
    if line_rest != '':
        return None
    return tm

def parse_date_from_filename(filename, fmt):
    tm = parse_with_format(filename, fmt)
    if tm is None:
        return None
    return tm

