# ---------------- colors / styles / theme ----------------

def ascii_lower(s):
    return ''.join(chr(ord(c)+32) if 'A' <= c <= 'Z' else c for c in s)

@dataclass(frozen=True)
class Color:
    kind: str = 'default'  # default|ansi16|ansi256|rgb
    value: object = None

COLOR_DEFAULT = Color('default', None)
def color_ansi16(i): return Color('ansi16', int(i))
def color_ansi256(i): return Color('ansi256', int(i))
def color_rgb(r,g,b): return Color('rgb', (int(r),int(g),int(b)))

class ColorError(Exception):
    pass

def _stoi_prefix(tok):
    m = re.match(r'^[+-]?\d+', tok)
    if not m:
        raise ColorError(f'Invalid numeric value in color: {tok}')
    try:
        v = int(m.group(0), 10)
    except Exception:
        raise ColorError(f'Invalid numeric value in color: {tok}')
    if v < -2147483648 or v > 2147483647:
        raise ColorError(f'Invalid numeric value in color: {tok}')
    return v

def _parse_int_list(inner):
    norm = inner.replace(',', ' ')
    tokens = [t for t in re.split(r'[ \t\r\n\v\f]+', norm) if t != '']
    return [_stoi_prefix(t) for t in tokens]

_ANSI16_NAMES = {
    'black':0,'red':1,'green':2,'yellow':3,'blue':4,'magenta':5,'cyan':6,'white':7,
    'brightblack':8,'brightred':9,'brightgreen':10,'brightyellow':11,'brightblue':12,'brightmagenta':13,'brightcyan':14,'brightwhite':15,
}

def parse_color(raw):
    s = raw
    if s == '':
        return COLOR_DEFAULT
    if ascii_lower(s) == 'default':
        return COLOR_DEFAULT
    if s.startswith('#'):
        if len(s) != 7:
            raise ColorError(f'Invalid hex color format: {s}')
        if any(c not in '0123456789abcdefABCDEF' for c in s[1:]):
            raise ColorError(f'Invalid hex color value: {s}')
        return color_rgb(int(s[1:3],16), int(s[3:5],16), int(s[5:7],16))
    open_idx = s.find('(')
    if open_idx < 0 or not s.endswith(')'):
        raise ColorError(f'Invalid color format: {s}')
    inner = s[open_idx+1:-1]
    if inner == '':
        raise ColorError(f'Invalid color format: {s}')
    fname = ascii_lower(s[:open_idx])
    if fname == 'rgb':
        vals = _parse_int_list(inner)
        if len(vals) != 3:
            raise ColorError(f'RGB color expects 3 values: {s}')
        if any(v < 0 or v > 255 for v in vals):
            raise ColorError(f'RGB values out of range: {s}')
        return color_rgb(*vals)
    if fname == 'rgba':
        vals = _parse_int_list(inner)
        if len(vals) != 4:
            raise ColorError(f'RGBA color expects 4 values: {s}')
        if any(v < 0 or v > 255 for v in vals[:3]):
            raise ColorError(f'RGBA values out of range: {s}')
        if vals[3] < 0 or vals[3] > 255:
            raise ColorError(f'RGBA alpha out of range: {s}')
        return color_rgb(vals[0],vals[1],vals[2])
    if fname == 'ansi256':
        vals = _parse_int_list(inner)
        if len(vals) != 1:
            raise ColorError(f'ansi256 expects 1 value: {s}')
        if vals[0] < 0 or vals[0] > 255:
            raise ColorError(f'ansi256 value out of range: {s}')
        return color_ansi256(vals[0])
    if fname == 'ansi16':
        t = _trim(inner)
        if t != '' and all('0' <= c <= '9' for c in t):
            # pure numeric
            try:
                v = int(t, 10)
            except Exception:
                raise ColorError(f'Invalid ansi16 numeric value: {t}')
            if v < -2147483648 or v > 2147483647:
                raise ColorError(f'Invalid ansi16 numeric value: {t}')
            if v < 0 or v > 15:
                raise ColorError(f'ansi16 value out of range: {t}')
            return color_ansi16(v)
        low = ascii_lower(t)
        if low in _ANSI16_NAMES:
            return color_ansi16(_ANSI16_NAMES[low])
        raise ColorError(f'Unknown ansi16 color name: {t}')
    raise ColorError(f'Unknown color format: {s}')

