_BORDER_STYLES={'light','dashed','heavy','double','rounded','empty'}

def _parse_style_section(root, section_path, default_style):
    node = root.direct(section_path)
    if node is None or len(node.children) == 0:
        return default_style.copy()
    st = Style()
    for key, attr in [('fgcolor','fg'),('bgcolor','bg')]:
        child = node.direct(key)
        if child is not None:
            raw = child.data
            try:
                col = parse_color(raw)
            except ColorError as e:
                raise AppError(f'Invalid {section_path}.{key} ({raw}): {e}')
            setattr(st, attr, col)
    for flag in ['italic','bold','underlined','dim','inverted','strikethrough','blink']:
        setattr(st, flag, ptree_get_bool(node, flag, False))
    return st

def _parse_markdown_theme(root, section_path):
    theme = MarkdownTheme()
    node = root.direct(section_path)
    if node is None:
        return theme
    mapping=[('header1','header1'),('header2','header2'),('header3','header3'),('header4','header4'),('header5','header5'),('header6','header6'),('list','list'),('quote','quote'),('code-fg','code_fg')]
    for key, attr in mapping:
        child = node.direct(key)
        if child is not None:
            raw = child.data
            try:
                col = parse_color(raw)
            except ColorError as e:
                raise AppError(f'Invalid {section_path}.{key} ({raw}): {e}')
            setattr(theme, attr, col)
    return theme

def _parse_border_raw(raw, display_path):
    if raw is None or raw == '':
        return 'rounded'
    low = ascii_lower(raw)
    if low not in _BORDER_STYLES:
        raise AppError(f'Invalid border style for {display_path}: {low}')
    return low

def _get_component_border(root, main_section, main_key, sub_section):
    # returns border style, honoring main-key precedence if the key node exists
    main_node = root.direct(main_section)
    if main_node is not None and main_node.has_direct(main_key):
        return _parse_border_raw(main_node.get_direct(main_key,''), f'{main_section}/{main_key}')
    if sub_section is not None:
        sub_node = root.direct(sub_section)
        if sub_node is not None and sub_node.has_direct('border'):
            return _parse_border_raw(sub_node.get_direct('border',''), f'{sub_section}/border')
    return 'rounded'

def _get_simple_border(root, main_section, main_key):
    main_node = root.direct(main_section)
    if main_node is not None and main_node.has_direct(main_key):
        return _parse_border_raw(main_node.get_direct(main_key,''), f'{main_section}/{main_key}')
    return 'rounded'

