def _split_cpp(s, delim='.'):
    if s == '':
        return []
    parts = s.split(delim)
    if s.endswith(delim):
        parts.pop()
    return parts

def _parse_event_date(s):
    orig = s
    # sscanf("%2d.%2d") emulation
    def parse_field(pos):
        # %d skips whitespace
        while pos < len(s) and s[pos] in ' \t\n\r\v\f':
            pos += 1
        start = pos
        if pos < len(s) and s[pos] in '+-':
            pos += 1
        digits = 0
        while pos < len(s) and '0' <= s[pos] <= '9' and (pos - start) < 2:
            pos += 1; digits += 1
        if digits == 0:
            raise ValueError()
        return int(s[start:pos],10), pos
    try:
        day,pos = parse_field(0)
        if pos >= len(s) or s[pos] != '.':
            raise ValueError()
        pos += 1
        month,pos = parse_field(pos)
    except Exception:
        raise AppError(f'Invalid date format: {orig}')
    return (day & 0xff, month & 0xff)

