ROOT_SECTION = '<root section>'

def _parse_tag_line(trimmed):
    if not trimmed.startswith('*'):
        return None
    # '*' + one or more literal spaces
    i = 1
    if i >= len(trimmed) or trimmed[i] != ' ':
        return None
    while i < len(trimmed) and trimmed[i] == ' ':
        i += 1
    start = i
    allowed = set('abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789 -')
    while i < len(trimmed) and trimmed[i] in allowed:
        i += 1
    name = trimmed[start:i].strip(' ')
    if name == '':
        return None
    name_low = ascii_lower(name)
    if i >= len(trimmed):
        return name_low
    ch = trimmed[i]
    if ch == ':':
        return name_low
    if ch == '(':
        last = trimmed.rfind(')')
        if last < 0:
            return None
        content = trimmed[i+1:last]
        if content == '':
            return None
        tail = trimmed[last+1:]
        if tail == '' or tail.startswith(':'):
            return name_low
        return None
    return None

@dataclass
class LogEntry:
    date: Date
