def parse_log_content(content: str, first_line_section: bool):
    sections = {}
    current = ROOT_SECTION
    # splitlines behavior: std::getline on \n; last trailing newline does not create an extra line for parsing
    lines = content.split('\n')
    for idx, rawline in enumerate(lines):
        trimmed = rawline.strip(_WS)
        if (idx > 0 or first_line_section) and trimmed.startswith('# '):
            name = ascii_lower(trimmed[2:].strip(_WS))
            if name != '':
                current = name
                sections[current] = []
                continue
        tag = _parse_tag_line(trimmed)
        if tag is not None:
            lst = sections.setdefault(current, [])
            if tag not in lst:
                lst.append(tag)
    return sections

