def _is_parent_path(parent, child):
    def comps(p):
        absolute = p.startswith('/')
        parts=[]
        for part in p.split('/'):
            if part=='' or part=='.':
                continue
            parts.append(part)
        return (absolute, parts)
    pa,pp = comps(parent); ca,cp = comps(child)
    if pa != ca:
        return False
    if len(pp) > len(cp):
        return False
    return cp[:len(pp)] == pp

