class MDLine:
    segments: list  # list[(text, Style)]
    full_style: object = None  # Style or None: if set, empty/trailing cells get this style

def _md_inline(text, base_style: Style, md: MarkdownTheme):
    # Returns segments [(text, Style)], applying inline code/bold/italic/strike/link/url.
    segs=[]
    buf=''
    def flush(style=None):
        nonlocal buf
        if buf:
            segs.append((buf, style.copy() if style else base_style.copy()))
            buf=''
    def add_plain(t, style):
        if t: segs.append((t, style.copy()))
    i=0
    n=len(text)
    while i<n:
        # code span
        if text[i]=='`':
            # count backticks
            j=i
            while j<n and text[j]=='`': j+=1
            ticks=j-i
            # find closing run of same length
            close=text.find('`'*ticks, j)
            if close>=0 and close>j:
                flush()
                add_plain('`'*ticks, base_style)
                cs=base_style.copy(); cs.fg=md.code_fg
                add_plain(text[j:close], cs)
                add_plain('`'*ticks, base_style)
                i=close+ticks; continue
            buf+=text[i]; i+=1; continue
        # bold ** / __
        if text.startswith('**',i) or text.startswith('__',i):
            delim=text[i:i+2]; close=text.find(delim,i+2)
            if close>i+2:
                flush(); add_plain(delim,base_style)
                bs=base_style.copy(); bs.bold=True
                # recursive inline inside bold (without re-parsing bold delimiters as italic naively is acceptable)
                inner=_md_inline(text[i+2:close], bs, md)
                segs.extend(inner)
                add_plain(delim,base_style); i=close+2; continue
        # strikethrough ~~
        if text.startswith('~~',i):
            close=text.find('~~',i+2)
            if close>i+2:
                flush(); add_plain('~~',base_style); ss=base_style.copy(); ss.strikethrough=True; segs.extend(_md_inline(text[i+2:close],ss,md)); add_plain('~~',base_style); i=close+2; continue
        # italic * or _
        if text[i] in '*_':
            delim=text[i]; close=text.find(delim,i+1)
            if close>i+1:
                # avoid treating a lone list-like * at start handled before; here generic
                flush(); add_plain(delim,base_style); isty=base_style.copy(); isty.italic=True; segs.extend(_md_inline(text[i+1:close],isty,md)); add_plain(delim,base_style); i=close+1; continue
        # link [text](url)
        if text[i]=='[':
            rb=text.find(']',i+1)
            if rb> i and rb+1<n and text[rb+1]=='(':
                rp=text.find(')',rb+2)
                if rp>=0:
                    flush(); add_plain('[',base_style)
                    ls=base_style.copy(); ls.fg=color_ansi16(4); ls.underlined=True
                    add_plain(text[i+1:rb],ls)
                    add_plain(text[rb:rp+1],base_style)
                    i=rp+1; continue
        # bare URL
        if text.startswith('http://',i) or text.startswith('https://',i):
            j=i
            while j<n and text[j] not in ' \t\r\n':
                j+=1
            flush(); ls=base_style.copy(); ls.fg=color_ansi16(4); ls.underlined=True; add_plain(text[i:j],ls); i=j; continue
        # escape
        if text[i]=='\\' and i+1<n and text[i+1] in '*_`~[]()#+-.!>':
            buf+=text[i]; i+=1; continue
        buf+=text[i]; i+=1
    flush()
    if not segs:
