    return segs

def render_markdown(content: str, md: MarkdownTheme):
    raw_lines = split_lines_getline(content)
    out=[]
    in_fence=False
    for raw in raw_lines:
        line = raw[:-1] if raw.endswith('\r') else raw
        stripped = line.strip(_WS)
        lstrip = line.lstrip(' \t')
        # fenced code delimiter: stripped starts with ```
        if stripped.startswith('```'):
            st=Style(fg=md.code_fg, dim=True)
            out.append(MDLine([(line, st.copy())], full_style=st.copy()))
            in_fence = not in_fence
            continue
        if in_fence:
            st=Style(fg=md.code_fg)
            out.append(MDLine([(line, st.copy())], full_style=st.copy()))
            continue
        # header at column 0: 1+ '#' + space
        m=re.match(r'^(#{1,})( )', line)
        if m:
            level=min(len(m.group(1)),6)
            cols=[md.header1,md.header2,md.header3,md.header4,md.header5,md.header6]
            st=Style(fg=cols[level-1], bold=(level<=2))
            out.append(MDLine([(line, st.copy())], full_style=st.copy()))
            continue
        # horizontal rule --- (3+ dashes, possibly spaces) observed dim
        if re.fullmatch(r'-{3,}', stripped):
            st=Style(dim=True)
            out.append(MDLine([(line, st.copy())], full_style=st.copy()))
            continue
        # list
        lm=re.match(r'^([ \t]*)(?:([*\-+]) |(\d+)\. )', line)
        if lm:
            indent=lm.group(1)
            marker_end=lm.end()
            base=Style()
            segs=[]
            if indent: segs.append((indent, Style()))
            mst=Style(fg=md.list, bold=True)
            segs.append((line[len(indent):marker_end], mst))
            segs.extend(_md_inline(line[marker_end:], base, md))
            out.append(MDLine(segs))
            continue
        # quote
        qm=re.match(r'^([ \t]*)(> ?)', line)
        if qm and lstrip.startswith('>'):
            indent=qm.group(1); marker=qm.group(2)
            segs=[]
            if indent: segs.append((indent, Style()))
            segs.append((marker, Style(fg=md.quote)))
            segs.extend(_md_inline(line[len(indent)+len(marker):], Style(), md))
            out.append(MDLine(segs))
            continue
        out.append(MDLine(_md_inline(line, Style(), md)))
    return out

