# ---------------- file helpers / repositories ----------------

def read_existing_bytes(path):
    if not fs_exists(path):
        return None
    if fs_is_dir(path):
        return b''
    try:
        with open(path,'rb') as f:
            return f.read()
    except IsADirectoryError:
        return b''
    except OSError:
        return None

def read_file_throw(path):
    try:
        with open(path,'rb') as f:
            return f.read()
    except OSError:
        raise AppError(f'Failed to open file: {fs_str(path)}')

def fs_remove_or_throw(path):
    # std::filesystem::remove
    try:
        st = os.lstat(path)
    except FileNotFoundError:
        return False
    except OSError as e:
        raise AppError(fs_error_msg('cannot remove', e.errno or errno.EIO, fs_str(path)))
    try:
        import stat as _stat
        if _stat.S_ISDIR(st.st_mode) and not os.path.islink(path):
            os.rmdir(path)
        else:
            os.remove(path)
        return True
    except OSError as e:
        raise AppError(fs_error_msg('cannot remove', e.errno or errno.EIO, fs_str(path)))

def parent_path_str(p):
    p = fs_str(p)
    # lexical parent like fs::path::parent_path
    # remove trailing slashes except root
    if p != '/':
        p2 = p.rstrip('/')
        if p2 == '':
            p2 = '/'
    else:
        p2 = p
    idx = p2.rfind('/')
    if idx < 0:
        return ''
    if idx == 0:
        return '/'
    return p2[:idx]

def split_lines_getline(content: str):
    if content == '':
        return []
    lines = content.split('\n')
    if content.endswith('\n'):
        lines.pop()
    return lines

