    marker = fs_join(cfg.log_dir, '.cle')
    is_enc = fs_exists(marker)
    if not decrypt and is_enc:
        raise AppError('Already applied')
    if decrypt and not is_enc:
        raise AppError('Already applied')
    errors = []
    def process(path):
        try:
            with open(path,'rb') as f:
                data = f.read()
            out = aes_cfb128(data, cfg.password_bytes(), decrypt=decrypt)
            with open(path,'wb') as f:
                f.write(out)
        except Exception:
            errors.append('std::exception')
    top = dir_entries(cfg.log_dir)
    for e in top:
        try:
            isdir = e.is_dir()
        except OSError:
            isdir = False
        if not isdir:
            continue
        if re.fullmatch(r'y[0-9]{4}', e.name):
            for sub in dir_entries(e.path):
                try:
                    isfile = sub.is_file()
                except OSError:
                    isfile=False
                if not isfile: continue
                if parse_date_from_filename(sub.name, cfg.log_filename_format) is None: continue
                process(sub.path)
        elif e.name == 'scratchpads':
            for sub in dir_entries(e.path):
                try:
                    isfile = sub.is_file()
                except OSError:
                    isfile=False
                if not isfile: continue
                process(sub.path)
