        # horizontal rule --- (3+ dashes, possibly spaces) observed dim
        if re.fullmatch(r'-{3,}', stripped):
            st=Style(dim=True)
            out.append(MDLine([(line, st.copy())], full_style=st.copy()))
            continue
        # list
        lm=re.match(r'^([ \t]*)(?:([*\-+]) |(\d+)\. )', line)
        if lm:
            indent=lm.group(1)
            marker_end=lm.end()
            base=Style()
            segs=[]
            if indent: segs.append((indent, Style()))
            mst=Style(fg=md.list, bold=True)
            segs.append((line[len(indent):marker_end], mst))
            segs.extend(_md_inline(line[marker_end:], base, md))
            out.append(MDLine(segs))
