def apply_automerge(grid):
    # compute new chars based on neighbor segments
    changes=[]
    for y in range(grid.h):
        for x in range(grid.w):
            c=grid.cells[y][x]
            if not c.seg: continue
            mask=c.seg
            if y>0 and (grid.cells[y-1][x].seg & SEG_S): mask|=SEG_N
            if y+1<grid.h and (grid.cells[y+1][x].seg & SEG_N): mask|=SEG_S
            if x>0 and (grid.cells[y][x-1].seg & SEG_E): mask|=SEG_W
            if x+1<grid.w and (grid.cells[y][x+1].seg & SEG_W): mask|=SEG_E
            nc=_junction_char(mask,c.bstyle)
            if nc: changes.append((x,y,nc))
    for x,y,nc in changes:
