def _sgr_for(styletuple):
    fg,bg,attrs=styletuple
    codes=[0]
    if attrs&BOLD: codes.append(1)
    if attrs&DIM: codes.append(2)
    if attrs&ITALIC: codes.append(3)
    if attrs&UNDER: codes.append(4)
    if attrs&BLINK: codes.append(5)
    if attrs&INVERT: codes.append(7)
    if attrs&STRIKE: codes.append(9)
    def add_color(col,is_bg):
        if col.kind=='ansi16':
            v=col.value
            if is_bg: codes.append((100+(v-8)) if v>=8 else (40+v))
            else: codes.append((90+(v-8)) if v>=8 else (30+v))
        elif col.kind=='ansi256':
            codes.append(48 if is_bg else 38); codes.append(5); codes.append(col.value)
        elif col.kind=='rgb':
            codes.append(48 if is_bg else 38); codes.append(2); codes.extend(col.value)
    if fg.kind!='default': add_color(fg,False)
    if bg.kind!='default': add_color(bg,True)
    return ('\x1b['+';'.join(str(c) for c in codes)+'m').encode()

@dataclass
class Event:
    kind: str  # key|char|mouse|resize|ctrlc
    value: object=None

class InputParser:
    def __init__(self):
        self.buf=b''
    def feed(self,data:bytes):
        self.buf += data
        events=[]
        while self.buf:
            ev, consumed = self._parse_one(self.buf)
            if consumed==0:
                break
            self.buf=self.buf[consumed:]
            if ev is not None:
                events.append(ev)
        return events
    def flush_escape(self):
        if self.buf==b'\x1b':
            self.buf=b''; return [Event('key','Escape')]
        return []
    def _parse_one(self,b):
        if not b: return None,0
        c=b[0]
        if c==0x1b:
            if len(b)==1:
                return None,0  # wait for possible sequence; caller may flush on timeout if desired (we treat immediately in read loop with timeout)
            if b[1:2]==b'[':
                # CSI: find final 0x40-0x7e
                i=2
                while i < len(b) and not (0x40 <= b[i] <= 0x7e):
                    i+=1
                if i>=len(b):
                    return None,0
                final=chr(b[i]); params=b[2:i].decode('ascii','ignore')
                consumed=i+1
                if params.startswith('<'):
                    # SGR mouse
                    try:
                        parts=params[1:].split(';'); btn=int(parts[0]); x=int(parts[1]); y=int(parts[2])
                    except Exception:
                        return None,consumed
                    press = (final=='M')
                    return Event('mouse',(btn,x-1,y-1,press)),consumed
                if final=='Z': return Event('key','ShiftTab'),consumed
                mp={'A':'Up','B':'Down','C':'Right','D':'Left','H':'Home','F':'End','P':'F1','Q':'F2','R':'F3','S':'F4'}
                if final in mp and (params=='' or re.fullmatch(r'[0-9;]*',params)):
                    return Event('key',mp[final]),consumed
                if final=='~':
                    try: code=int(params.split(';')[0]) if params else 0
                    except: code=0
                    mm={1:'Home',2:'Insert',3:'Delete',4:'End',5:'PageUp',6:'PageDown',7:'Home',8:'End',11:'F1',12:'F2',13:'F3',14:'F4',15:'F5',17:'F6',18:'F7',19:'F8',20:'F9',21:'F10',23:'F11',24:'F12',200:'PasteStart',201:'PasteEnd'}
                    if code in mm: return Event('key',mm[code]),consumed
                    return None,consumed
                if final=='u':
                    # kitty keyboard: codepoint;modifiers - ignore / translate some
                    return None,consumed
                return None,consumed
            elif b[1:2]==b'O':
                if len(b)<3: return None,0
                final=chr(b[2]); mp={'A':'Up','B':'Down','C':'Right','D':'Left','H':'Home','F':'End','P':'F1','Q':'F2','R':'F3','S':'F4'}
                return (Event('key',mp[final]) if final in mp else None),3
            elif b[1:2]==b'P':
                # DCS sequence from terminal responses: consume till ST (ESC \) if present, else wait / drop few
                end=b.find(b'\x1b\\')
                if end<0:
                    return None,0 if len(b)<20 else len(b)
                return None,end+2
            else:
                # ESC + char: if next is ESC, emit Escape for first
                if b[1]==0x1b:
                    return Event('key','Escape'),1
                # Alt+char or standalone escape followed by a normal key in same chunk:
                # FTXUI parses ESC as Escape event then the char separately in many cases; emulate Escape only.
                return Event('key','Escape'),1
        if c==3:
            return Event('ctrlc',None),1
        if c==9:
            return Event('key','Tab'),1
        if c in (13,10):
            return Event('key','Enter'),1
        if c in (127,8):
            return Event('key','Backspace'),1
        if c<32:
            if 1<=c<=26:
                return Event('key',f'Ctrl+{chr(96+c)}'),1
            return None,1
        # UTF-8 char
        # determine length
        if c<0x80:
            return Event('char',chr(c)),1
        # multibyte
        for ln in (2,3,4):
            if len(b)>=ln:
                try:
                    ch=b[:ln].decode('utf-8')
                    if len(ch)==1: return Event('char',ch),ln
                except Exception:
                    pass
        # incomplete sequence?
        if len(b)<4:
            # could be incomplete; check if it is a valid prefix
            try:
                b.decode('utf-8')
            except UnicodeDecodeError as e:
                if e.reason=='unexpected end of data':
                    return None,0
            except Exception:
                pass
        return Event('char',chr(c)),1

class Terminal:
    def __init__(self):
        self.out=sys.stdout.buffer
        try:
            self.infd=sys.stdin.buffer.fileno()
        except Exception:
            self.infd=0
        self.width,self.height=self.get_size()
        self._orig=None
        self.parser=InputParser()
        self._eof=False
        self._wake_r,self._wake_w=os.pipe()
        os.set_blocking(self._wake_r,False); os.set_blocking(self._wake_w,False)
        self._sigwinch=False; self._sigint=False; self._sigterm=False
        try:
            signal.set_wakeup_fd(self._wake_w)
        except Exception:
            pass
        def hwinch(signum,frame): self._sigwinch=True
        def hint(signum,frame): self._sigint=True
        def hterm(signum,frame): self._sigterm=True
        try: signal.signal(signal.SIGWINCH,hwinch)
        except Exception: pass
        try: signal.signal(signal.SIGINT,hint)
        except Exception: pass
        try: signal.signal(signal.SIGTERM,hterm)
        except Exception: pass
    def get_size(self):
        for fd in (1,0,2):
            try:
                sz=os.get_terminal_size(fd)
                if sz.columns>0 and sz.lines>0: return sz.columns,sz.lines
            except Exception:
                pass
        try:
            c=int(os.environ.get('COLUMNS','80')); l=int(os.environ.get('LINES','24'))
            if c>0 and l>0: return c,l
        except Exception:
            pass
        return 80,24
    def enter(self):
        # raw mode if tty
        try:
            import termios
            self._orig=termios.tcgetattr(self.infd)
            raw=termios.tcgetattr(self.infd)
            # cfmakeraw-like
            raw[0] &= ~(termios.BRKINT | termios.ICRNL | termios.INPCK | termios.ISTRIP | termios.IXON)
            raw[1] &= ~(termios.OPOST)
            raw[2] |= termios.CS8
            raw[3] &= ~(termios.ECHO | termios.ICANON | termios.IEXTEN | termios.ISIG)
            raw[6][termios.VMIN]=0
            raw[6][termios.VTIME]=0
            termios.tcsetattr(self.infd,termios.TCSANOW,raw)
        except Exception:
            self._orig=None
        self.out.write(b'\x1b[?1049h\x1b[?7l\x1b[?1000h\x1b[?1003h\x1b[?1015h\x1b[?1006h\x1b[?25l\x1b[H\x1b[2J')
        self.out.flush()
    def exit(self):
        try:
            self.out.write(b'\x1b[?1006l\x1b[?1015l\x1b[?1003l\x1b[?1000l\x1b[?7h\x1b[?1049l\x1b[?25h')
            self.out.flush()
        except Exception:
            pass
        if self._orig is not None:
            try:
                import termios; termios.tcsetattr(self.infd,termios.TCSANOW,self._orig)
            except Exception:
                pass
    def suspend(self):
        self.exit()
    def resume(self):
        # re-enter raw + alt; re-save orig was restored, enter() re-reads it
        self.enter()
    def render(self,grid,cursor=None):
        apply_automerge(grid)
        out=bytearray(); out+=b'\x1b[H'
        for y in range(grid.h):
            cur=None
            for x in range(grid.w):
                c=grid.cells[y][x]
                if c.cont: continue
                st=(c.fg,c.bg,c.attrs)
                if st!=cur:
                    out+=_sgr_for(st); cur=st
                out+=(c.ch if c.ch else ' ').encode('utf-8','surrogateescape')
            out+=b'\x1b[0m'
            if y+1<grid.h: out+=b'\r\n'
        if cursor is not None:
            cx,cy=cursor
            out+=(f'\x1b[{cy+1};{cx+1}H\x1b[?25h').encode()
        else:
            out+=b'\x1b[?25l'
        try:
            self.out.write(bytes(out)); self.out.flush()
        except BrokenPipeError:
            raise ExitApp(0)
    def read_event(self):
        # blocking: returns one Event
        while True:
            if self._sigint or self._sigterm:
                self._sigint=False; self._sigterm=False
                return Event('ctrlc',None)
            if self._sigwinch:
                self._sigwinch=False; self.width,self.height=self.get_size(); return Event('resize',None)
            fds=[] if self._eof else [self.infd]
            fds.append(self._wake_r)
            try:
                r,_,_=__import__('select').select(fds,[],[],0.2)
            except Exception:
                r=[]
            if self._wake_r in r:
                try: os.read(self._wake_r,4096)
                except Exception: pass
                continue
            if self.infd in r:
                try:
                    data=os.read(self.infd,65536)
                except OSError:
                    data=b''
                if data==b'':
                    self._eof=True; continue
                evs=self.parser.feed(data)
                if evs:
                    # queue extras
                    self._queued=getattr(self,'_queued',[])+evs[1:]
                    return evs[0]
                # if a lone ESC remained, treat as Escape after input parse (terminal sends sequences atomically in tests)
                fe=self.parser.flush_escape()
                if fe: return fe[0]
                continue
            q=getattr(self,'_queued',[])
            if q:
                self._queued=q[1:]; return q[0]
            # timeout: loop to check signals / flush lone escape if pending
            fe=self.parser.flush_escape()
            if fe: return fe[0]

