# ---------------- terminal framework ----------------

BOLD=1; DIM=2; ITALIC=4; UNDER=8; BLINK=16; INVERT=32; STRIKE=64

def style_to_cell(style: Style, extra_attrs=0):
    attrs=extra_attrs
    if style.bold: attrs|=BOLD
    if style.dim: attrs|=DIM
    if style.italic: attrs|=ITALIC
    if style.underlined: attrs|=UNDER
    if style.blink: attrs|=BLINK
    if style.inverted: attrs|=INVERT
    if style.strikethrough: attrs|=STRIKE
    return (style.fg, style.bg, attrs)

def cell_style(attrs=0, fg=COLOR_DEFAULT, bg=COLOR_DEFAULT):
    return (fg,bg,attrs)

def _char_width(ch):
    if ch=='':
        return 0
    o=ord(ch)
    if o<32 or (127<=o<160):
        return 0
    if unicodedata.combining(ch):
        return 0
    if unicodedata.east_asian_width(ch) in ('W','F'):
        return 2
    return 1

def text_width(s):
    return sum(_char_width(c) for c in s)

class Cell:
    __slots__=('ch','fg','bg','attrs','seg','bstyle','cont')
    def __init__(self):
        self.ch=' '; self.fg=COLOR_DEFAULT; self.bg=COLOR_DEFAULT; self.attrs=0; self.seg=0; self.bstyle=None; self.cont=False
    def set(self,ch,style,seg=0,bstyle=None):
        self.ch=ch; self.fg,self.bg,self.attrs=style; self.seg=seg; self.bstyle=bstyle; self.cont=False

class Grid:
    def __init__(self,w,h):
        self.w=max(0,w); self.h=max(0,h)
        self.cells=[[Cell() for _ in range(self.w)] for __ in range(self.h)]
    def inb(self,x,y): return 0<=x<self.w and 0<=y<self.h
    def set(self,x,y,ch,style,seg=0,bstyle=None):
        if self.inb(x,y):
            self.cells[y][x].set(ch,style,seg,bstyle)
    def text(self,x,y,s,style,clip_x1=None):
        if y<0 or y>=self.h: return
        cx=x
        limit=self.w if clip_x1 is None else min(self.w,clip_x1)
        for ch in s:
            w=_char_width(ch)
            if w==0:
                continue
            if cx>=limit: break
            if cx>=0:
                self.set(cx,y,ch,style)
                if w==2 and cx+1<limit:
                    c=self.cells[y][cx+1]; c.set('',style); c.cont=True
            cx+=w
        return cx
    def fill_rect_style(self,x,y,w,h,style):
        for yy in range(y,y+h):
            for xx in range(x,x+w):
                if self.inb(xx,yy):
                    c=self.cells[yy][xx]
                    # only apply style to existing char if it is space? caller uses before drawing
                    if c.ch==' ':
                        c.fg,c.bg,c.attrs=style
    def add_dim_all(self):
        for row in self.cells:
            for c in row:
                c.attrs|=DIM

