def draw_box(grid,x,y,w,h,border_style,style,title=None):
    if w<=0 or h<=0: return
    if border_style not in _BORDER_CHARS: border_style='rounded'
    tl,tr,bl,br,hz,vt=_BORDER_CHARS[border_style]
    merge = border_style!='empty'
    # top and bottom
    for xx in range(x,x+w):
        seg=0
        if merge: seg=SEG_E|SEG_W
        grid.set(xx,y,hz,style,seg,border_style)
        if h>1:
            grid.set(xx,y+h-1,hz,style,seg,border_style)
    for yy in range(y,y+h):
        seg=SEG_N|SEG_S if merge else 0
        grid.set(x,yy,vt,style,seg,border_style)
        if w>1:
            grid.set(x+w-1,yy,vt,style,seg,border_style)
    # corners
    grid.set(x,y,tl,style,(SEG_E|SEG_S) if merge else 0,border_style)
    if w>1: grid.set(x+w-1,y,tr,style,(SEG_W|SEG_S) if merge else 0,border_style)
    if h>1:
        grid.set(x,y+h-1,bl,style,(SEG_E|SEG_N) if merge else 0,border_style)
        if w>1: grid.set(x+w-1,y+h-1,br,style,(SEG_W|SEG_N) if merge else 0,border_style)
    if title:
        # title starts right after top-left corner, truncated to w-2
        grid.text(x+1,y,title,style,clip_x1=x+w-1)

