# ---------------- git sync (via git CLI, libgit2-like messages) ----------------

class GitError(AppError):
    def __init__(self, line, msg):
        super().__init__(f'Git error @/workspace/source/utils/git_repo.cpp:{line}\n\t{msg}')
        self.git_line=line; self.git_msg=msg

def _git_env(cfg: Config):
    env=dict(os.environ)
    env['GIT_TERMINAL_PROMPT']='0'
    if cfg.git.ssh_key:
        # libgit2 uses the supplied key pair directly; approximate with OpenSSH.
        env['GIT_SSH_COMMAND']=f"ssh -i {cfg.git.ssh_key} -o IdentitiesOnly=yes -o BatchMode=yes"
    return env

def _git_run(cfg: Config, args, check=False):
    try:
        return subprocess.run(['git','-C',cfg.git.repo_root]+args, capture_output=True, text=True, env=_git_env(cfg))
    except FileNotFoundError:
        # git binary missing: emulate a generic failure
        class R: pass
        r=R(); r.returncode=1; r.stdout=''; r.stderr='git not found'; return r

def git_open_check(cfg: Config):
    root=cfg.git.repo_root
    ok=False
    # Exact repository at root (root/.git or root itself a git dir)
    if fs_exists(fs_join(root,'.git')):
        ok=True
    else:
        # bare repo: HEAD + objects + refs in root
        if fs_exists(fs_join(root,'HEAD')) and fs_is_dir(fs_join(root,'objects')):
            ok=True
    if not ok:
        raise GitError(95, f"could not find repository from '{root}'")

def _map_fetch_error(stderr: str):
    txt=stderr.strip()
    # OpenSSH resolution
    m=re.search(r'Could not resolve hostname ([^: ]+)', txt)
    if m:
        return f"failed to resolve address for {m.group(1)}: Temporary failure in name resolution"
    m=re.search(r'connect to host ([^ ]+) port \d+: (.+)', txt)
    if m:
        return f"failed to connect to {m.group(1)}: {m.group(2).strip()}"
    m=re.search(r'failed to start SSH session.*', txt, re.I)
    if m: return m.group(0)
    lines=[l.strip() for l in txt.splitlines() if l.strip()]
    if lines:
        last=lines[-1]
        last=re.sub(r'^(fatal|error):\s*','',last, flags=re.I)
        return last
    return 'failed to fetch'

def git_pull(cfg: Config):
    git_open_check(cfg)
    r=_git_run(cfg,['remote'])
    remotes=[l.strip() for l in r.stdout.splitlines()] if r.returncode==0 else []
    if cfg.git.remote not in remotes:
        raise GitError(213, f"remote '{cfg.git.remote}' does not exist")
    fr=_git_run(cfg,['fetch',cfg.git.remote])
    if fr.returncode!=0:
        raise GitError(218, _map_fetch_error(fr.stderr or fr.stdout))
    ref=f"refs/remotes/{cfg.git.remote}/{cfg.git.branch}"
    rr=_git_run(cfg,['rev-parse','--verify','-q',ref+'^{commit}'])
    if rr.returncode!=0:
        raise GitError(222, f"reference '{ref}' not found")
    remote_oid=rr.stdout.strip()
    hr=_git_run(cfg,['rev-parse','--verify','-q','HEAD^{commit}'])
    if hr.returncode!=0:
        # No local commit: libgit2 merge behaviour is obscure; reset to remote if possible
        _git_run(cfg,['reset','--hard',remote_oid])
        return
    head_oid=hr.stdout.strip()
    if head_oid==remote_oid:
        return
    anc=_git_run(cfg,['merge-base','--is-ancestor',head_oid,remote_oid])
    if anc.returncode==0:
        rs=_git_run(cfg,['reset','--hard',remote_oid])
        if rs.returncode!=0:
            raise GitError(218, _map_fetch_error(rs.stderr or rs.stdout))
    # diverged / local ahead: do nothing (observed)

def git_commit(cfg: Config):
    # returns True if a commit was created, False if no changes
    git_open_check(cfg)
    st=_git_run(cfg,['status','--porcelain'])
    if st.returncode==0 and st.stdout.strip()=='':
        return False
    # signature validation like libgit2 git_signature_default (name first)
    name=_git_run(cfg,['config','user.name'])
    if name.returncode!=0:
        raise GitError(36, "config value 'user.name' was not found")
    email=_git_run(cfg,['config','user.email'])
    if email.returncode!=0:
        raise GitError(36, "config value 'user.email' was not found")
    add=_git_run(cfg,['add','-A'])
    if add.returncode!=0:
        raise GitError(36, _map_fetch_error(add.stderr or add.stdout))
    com=_git_run(cfg,['commit','-m','caps-log auto push'])
    if com.returncode!=0:
        # If nothing to commit after add (race), treat as no commit
        if 'nothing to commit' in (com.stdout+com.stderr):
            return False
        raise GitError(36, _map_fetch_error(com.stderr or com.stdout))
    return True

def git_push(cfg: Config):
    r=_git_run(cfg,['remote'])
    remotes=[l.strip() for l in r.stdout.splitlines()] if r.returncode==0 else []
    if cfg.git.remote not in remotes:
        raise GitError(149, f"remote '{cfg.git.remote}' does not exist")
    refspec=f"refs/heads/{cfg.git.branch}:refs/heads/{cfg.git.branch}"
    pr=_git_run(cfg,['push',cfg.git.remote,refspec])
    if pr.returncode!=0:
        raise GitError(149, _map_fetch_error(pr.stderr or pr.stdout))

