class App:
    def __init__(self, cfg: Config, needs_password=False, fatal_after_password=None):
        self.cfg=cfg
        self.repo=Repository(cfg)
        self.needs_password=needs_password
        self.term=Terminal()
        self.today=today_local()
        self.selected_date=self.today
        self.view='annual'  # annual|scratch
        self.phase='password' if needs_password else 'main'  # password|main|git_error|exit_loading
        self.focus=0  # 0 sections 1 tags 2 calendar 3 preview
        self.entries={}
        self.sections=[]  # list[(name_or_None,count)]
        self.tags=[]
        self.sec_idx=0; self.tag_idx=0
        self.preview_scroll=0
        self.scratch_items=[]
        self.scratch_idx=0
        self.scratch_loaded=False
        self.modal=None  # dict with kind etc
        self.show_help=False
        self._fatal=None
        self._exiting=False
        self._exit_code=0
        # git pull state
        self.pull_running=False; self.pull_done=False; self.pull_error=None; self.pull_handled=True; self.pull_stuck=False
        self._pull_thread=None
        self.git_error_text=''
        self.git_error_after='main'  # main|exit
        self.loading_status=''
        if not needs_password:
            self.repo.encrypted = bool(cfg.password) and self.repo.has_marker()
            self.refresh_logs(reset=True)
        else:
            self.repo.encrypted=False
            self.entries={}; self.recompute_menus()
            self.open_password_modal()
    # ---------- data ----------
    def refresh_logs(self, reset=False):
        if self.phase=='password':
            self.entries={}
        else:
            self.entries=self.repo.load_year(self.selected_date.y)
        if reset:
            self.sec_idx=0; self.tag_idx=0
        self.recompute_menus()
    def recompute_menus(self):
        sec_dates={}
        for dt,e in self.entries.items():
            for sec in e.sections.keys():
                sec_dates.setdefault(sec,set()).add(dt)
        sec_names=sorted(sec_dates.keys(), key=lambda s: s.encode('utf-8','surrogateescape'))
        self.sections=[(None,0)]+[(s,len(sec_dates[s])) for s in sec_names]
        if self.sec_idx>=len(self.sections): self.sec_idx=max(0,len(self.sections)-1)
        sel_sec=self.selected_section()
        tag_dates={}
        for dt,e in self.entries.items():
            if sel_sec is None:
                alltags=set()
                for lst in e.sections.values(): alltags.update(lst)
                for t in alltags: tag_dates.setdefault(t,set()).add(dt)
            else:
                for t in e.sections.get(sel_sec,[]): tag_dates.setdefault(t,set()).add(dt)
        tag_names=sorted(tag_dates.keys(), key=lambda s: s.encode('utf-8','surrogateescape'))
        self.tags=[(None,0)]+[(t,len(tag_dates[t])) for t in tag_names]
        if self.tag_idx>=len(self.tags): self.tag_idx=max(0,len(self.tags)-1)
    def selected_section(self):
        if not self.sections: return None
        return self.sections[max(0,min(self.sec_idx,len(self.sections)-1))][0]
    def selected_tag(self):
        if not self.tags: return None
        return self.tags[max(0,min(self.tag_idx,len(self.tags)-1))][0]
    def is_highlighted(self,dt):
        e=self.entries.get(dt)
        if e is None: return False
        stag=self.selected_tag(); ssec=self.selected_section()
        if stag is not None:
            if ssec is not None:
                return stag in e.sections.get(ssec,[])
            return any(stag in lst for lst in e.sections.values())
        if ssec is not None:
            return ssec in e.sections
        return False
    def event_relative(self, ev: CalEvent):
        ordinal=days_from_civil(self.today.y, ev.month, ev.day)
        return ordinal - self.today.ordinal()
    def recent_event_lines(self):
        lines=[]; count=0
        for cat in sorted(self.cfg.events_by_cat.keys(), key=lambda s:s.encode('utf-8','surrogateescape')):
            evs=sorted(self.cfg.events_by_cat[cat], key=lambda ev: ev.name.encode('utf-8','surrogateescape'))
            included=[]
            for ev in evs:
                diff=self.event_relative(ev)
                if abs(diff) <= self.cfg.recent_window:
                    if diff==0: rel='(today)'
                    elif diff>0: rel=f'(in {diff} days)'
                    else: rel=f'({-diff} days ago)'
                    included.append(f" - {ev.name} {ev.month:02d}.{ev.day:02d}. {rel}")
            if included:
                lines.append(cat); lines.extend(included); count+=len(included)
        return lines,count
    def todays_event_text(self):
        txt=''
        for cat in sorted(self.cfg.events_by_cat.keys(), key=lambda s:s.encode('utf-8','surrogateescape')):
            evs=sorted(self.cfg.events_by_cat[cat], key=lambda ev: ev.name.encode('utf-8','surrogateescape'))
            for ev in evs:
                if ev.month==self.today.m and ev.day==self.today.d:
                    txt=f"{cat} - {ev.name}"
        return txt
    # ---------- modal helpers ----------
    def open_password_modal(self):
        self.modal={'kind':'password','title':'Enter password for log files:','input':'','cursor':0,'password':True,'buttons':['Submit'],'focus':'input','btn_idx':0}
    def open_input_modal(self,kind,title):
        self.modal={'kind':kind,'title':title,'input':'','cursor':0,'password':False,'buttons':['Submit'],'focus':'input','btn_idx':0}
    def open_confirm(self,kind,title):
        self.modal={'kind':kind,'title':title,'buttons':['Yes','No'],'focus':'buttons','btn_idx':0}
    def open_message_ok(self,title):
        self.modal={'kind':'message_ok','title':title,'buttons':['Ok'],'focus':'buttons','btn_idx':0}
    # ---------- editor ----------
    def run_editor(self, path):
        if 'EDITOR' not in os.environ:
            return False
        editor=os.environ.get('EDITOR','')
        cmd=f"{editor} {path}"
        self.term.suspend()
        try:
            subprocess.run(cmd, shell=True, executable='/bin/sh')
        finally:
            self.term.resume()
            self.term.width,self.term.height=self.term.get_size()
        return True
    def temp_edit_path(self):
        tmpdir=os.environ.get('TMPDIR', None)
        if tmpdir is None:
            tmpdir='/tmp'
        else:
            if tmpdir=='' or not fs_is_dir(tmpdir):
                raise AppError('Invalid argument')
        return fs_join(tmpdir, f"caps-log-edit-{random.randint(100000,999999)}.md")
    def open_log_editor(self):
        if 'EDITOR' not in os.environ:
            return
        dt=self.selected_date
        path=self.repo.log_path(dt)
        header=f"# {fmt_date_dots(dt)}".encode()
        def cleanup_or_save(content_bytes):
            if content_bytes==b'' or content_bytes.strip(b' \t\n')==header:
                if fs_exists(path) or os.path.lexists(path):
                    fs_remove_or_throw(path)
                return
            if self.repo.encrypted:
                parent=parent_path_str(path)
                if parent: cpp_create_directories(parent)
                with open(path,'wb') as f: f.write(aes_cfb128(content_bytes,self.cfg.password_bytes(),decrypt=False))
            # unencrypted: file already edited in place
        if self.repo.encrypted:
            tmp=self.temp_edit_path()
            entry=self.entries.get(dt)
            initial = entry.content.encode('utf-8','surrogateescape') if entry is not None else header
            with open(tmp,'wb') as f: f.write(initial)
            self.run_editor(tmp)
            new=read_existing_bytes(tmp)
            if new is None: new=b''
            cleanup_or_save(new)
        else:
            if not fs_exists(path):
                parent=parent_path_str(path)
                if parent: cpp_create_directories(parent)
                with open(path,'wb') as f: f.write(header)
            self.run_editor(path)
            new=read_existing_bytes(path)
            if new is None: new=b''
            # for unencrypted, cleanup only (no rewrite)
            if new==b'' or new.strip(b' \t\n')==header:
                if fs_exists(path) or os.path.lexists(path):
                    fs_remove_or_throw(path)
        self.refresh_logs(reset=True)
        self.preview_scroll=0
    def open_scratchpad_editor(self, path):
        if 'EDITOR' not in os.environ:
            return
        if self.repo.encrypted:
            tmp=self.temp_edit_path()
            if fs_exists(path):
                raw=read_existing_bytes(path)
                if raw is None: raw=b''
                plain=aes_cfb128(raw,self.cfg.password_bytes(),decrypt=True)
                with open(tmp,'wb') as f: f.write(plain)
            self.run_editor(tmp)
            new=read_existing_bytes(tmp)
            if new is None: new=b''
            enc=aes_cfb128(new,self.cfg.password_bytes(),decrypt=False)
            # std::ofstream-like: if parent missing, write fails silently (no file). Mimic that.
            try:
                with open(path,'wb') as f: f.write(enc)
            except OSError:
                pass
        else:
            self.run_editor(path)
        # reload list when back in scratch view
        self.load_scratchpads(reset=True)
    def load_scratchpads(self, reset=False):
        self.scratch_items=self.repo.list_scratchpads()
        self.scratch_loaded=True
        if reset:
            self.scratch_idx=0
        else:
            # menu has +1 for Make new
            maxidx=len(self.scratch_items)
            if self.scratch_idx>maxidx: self.scratch_idx=maxidx
    # ---------- git pull in thread ----------
    def start_pull(self):
        if not self.cfg.git.enabled:
            return
        self.pull_running=True; self.pull_done=False; self.pull_error=None; self.pull_handled=False; self.loading_status='Pulling from remote...'
        import threading
        def work():
            try:
                git_pull(self.cfg)
            except AppError as e:
                msg=str(e).replace('\n','').replace('\t','')
                self.pull_error=f'Error pulling from remote:{msg}'
            except Exception as e:
                self.pull_error=f'Error pulling from remote:{e}'
            finally:
                self.pull_running=False; self.pull_done=True
                try: os.write(self.term._wake_w,b'G')
                except Exception: pass
        self._pull_thread=threading.Thread(target=work,daemon=True); self._pull_thread.start()
    def check_pull_done(self):
        if self.pull_done and not self.pull_handled:
            self.pull_handled=True
            if self.pull_error:
                self.git_error_text=self.pull_error
                self.git_error_after='main_stuck'
                self.phase='git_error'
            else:
                self.pull_stuck=False
                self.refresh_logs(reset=True)
    # ---------- main loop ----------
    def run(self):
        self.term.enter()
        try:
            if self.phase!='password' and self.cfg.git.enabled:
                self.start_pull()
            while True:
                self.check_pull_done()
                grid,cursor=self.render()
                self.term.render(grid,cursor)
                ev=self.term.read_event()
                if ev.kind=='ctrlc':
                    if self.phase=='git_error':
                        break
                    # graceful exit with optional git sync
                    self.begin_exit()
                    break
                if ev.kind=='resize' or ev.kind=='wake':
                    continue
                self.handle_event(ev)
                if self._fatal is not None:
                    raise AppError(self._fatal)
                if self._exiting:
                    break
        finally:
            self.term.exit()
        return self._exit_code
    def begin_exit(self):
        # Called on q/Escape/CtrlC from main views. Handles git exit sync in-phase.
        if not self.cfg.git.enabled or self.phase=='password':
            self._exiting=True; return
        # If pull is stuck with error (small modal), original still commits on Ctrl+C and exits.
        self.pull_stuck=False
        # Commit stage
        try:
            self.loading_status='Committing to remote...'
            grid,cursor=self.render(); self.term.render(grid,cursor)
            created=git_commit(self.cfg)
        except AppError as e:
            msg=str(e).replace('\n','').replace('\t','')
            self.git_error_text=f'Error committing to remote:{msg}'
            self.git_error_after='exit'; self.phase='git_error'; return
        if not created:
            self._exiting=True; return
        try:
            self.loading_status='Pushing to remote...'
            grid,cursor=self.render(); self.term.render(grid,cursor)
            git_push(self.cfg)
        except AppError as e:
            msg=str(e).replace('\n','').replace('\t','')
            self.git_error_text=f'Error pushing to remote:{msg}'
            self.git_error_after='exit'; self.phase='git_error'; return
        self._exiting=True
    # ---------- event handling ----------
    def handle_event(self,ev):
        # git error full screen: only Ok button (Enter) / Tab cycles single button
        if self.phase=='git_error':
            if ev.kind=='key' and ev.value=='Enter':
                if self.git_error_after=='exit':
                    self._exiting=True
                else:
                    self.phase='main'; self.pull_stuck=True; self.loading_status=self.git_error_text
            return
        if self.show_help:
            if ev.kind=='key' and ev.value=='Enter':
                self.show_help=False
            return
        if self.modal is not None:
            self.handle_modal_event(ev); return
        # small loading modal blocks input
        if self.pull_running or self.pull_stuck:
            return
        # keys translated later per-view
        if ev.kind=='mouse':
            self.handle_mouse(ev); return
        if ev.kind=='key' and ev.value=='F1':
            self.show_help=True; return
        # character keys
        ch = ev.value if ev.kind=='char' else None
        key = ev.value if ev.kind=='key' else None
        # global quit (only reached if not modal/help)
        if ch=='q' or key=='Escape':
            self.begin_exit(); return
        if self.phase=='password':
            return  # password modal handles (modal is set); unreachable
        if self.view=='annual':
            self.handle_annual(ev,ch,key)
        else:
            self.handle_scratch(ev,ch,key)
    def translate_dir(self,ch,key):
        if ch=='h': return 'Left'
        if ch=='j': return 'Down'
        if ch=='k': return 'Up'
        if ch=='l': return 'Right'
        if key in ('Left','Right','Up','Down'): return key
        return None
    def handle_annual(self,ev,ch,key):
        # global annual keys first for some chars not consumed by focused components are handled
        # in an order approximating FTXUI: focused component gets nav keys, then app-level chars.
        d=self.translate_dir(ch,key)
        # Tab focus
        if key=='Tab':
            self.focus=(self.focus+1)%4; return
        if key=='ShiftTab':
            self.focus=(self.focus-1)%4; return
        # Focused component navigation
        if self.focus in (0,1):
            # menus
            idx_attr='sec_idx' if self.focus==0 else 'tag_idx'
            lst=self.sections if self.focus==0 else self.tags
            cur=getattr(self,idx_attr)
            new=cur
            if d=='Down': new=min(cur+1,len(lst)-1)
            elif d=='Up': new=max(cur-1,0)
            elif key=='PageDown':
                # page size = visible menu height-1 (approx from last render: store)
                step=getattr(self,'_menu_page_step',17); new=min(cur+step,len(lst)-1)
            elif key=='PageUp':
                step=getattr(self,'_menu_page_step',17); new=max(cur-step,0)
            elif key=='Enter':
                return  # consumed, no-op
            if new!=cur:
                setattr(self,idx_attr,new)
                if self.focus==0:
                    self.tag_idx=0; self.recompute_menus()
                return
            if d is not None or key in ('PageDown','PageUp'):
                return
            # fall through to app keys (s,d,+,-,F1 handled, Enter already)
        elif self.focus==2:
            # calendar
            moved=False
            target=self.selected_date
            if d=='Left': target=self.selected_date.add_days(-1); moved=True
            elif d=='Right': target=self.selected_date.add_days(1); moved=True
            elif d=='Down': target=self.selected_date.add_days(7); moved=True
            elif d=='Up': target=self.selected_date.add_days(-7); moved=True
            elif key=='Enter':
                self.open_log_editor(); return
            if moved:
                if target.y==self.selected_date.y:
                    self.selected_date=target; self.preview_scroll=0
                return
        elif self.focus==3:
            # preview scroll
            lines=self._current_preview_lines()
            maxoff=max(0,len(lines)-1) if lines else 0
            if d=='Down': self.preview_scroll=min(self.preview_scroll+1,maxoff); return
            if d=='Up': self.preview_scroll=max(self.preview_scroll-1,0); return
            if d is not None: return
            if key=='Enter': return
        # app-level keys (component did not consume)
        if ch=='s':
            # entering scratch view loads list (may throw)
            self.load_scratchpads(reset=True)
            self.view='scratch'; return
        if ch=='+':
            self.selected_date=self.selected_date.add_years(1); self.preview_scroll=0; self.refresh_logs(reset=True); return
        if ch=='-':
            self.selected_date=self.selected_date.add_years(-1); self.preview_scroll=0; self.refresh_logs(reset=True); return
        if ch=='d' and self.focus==2:
            if self.selected_date in self.entries:
                self.open_confirm('delete_log','Are you sure you want to delete a log file?')
            return
        # Enter in calendar is handled above; in other focuses it's a no-op
    def handle_scratch(self,ev,ch,key):
        d=self.translate_dir(ch,key)
        total=1+len(self.scratch_items)
        # Menu gets Tab as wrap navigation (observed)
        if key=='Tab':
            if total: self.scratch_idx=(self.scratch_idx+1)%total
            return
        if key=='ShiftTab':
            if total: self.scratch_idx=(self.scratch_idx-1)%total
            return
        if d=='Down':
            self.scratch_idx=min(self.scratch_idx+1,total-1); return
        if d=='Up':
            self.scratch_idx=max(self.scratch_idx-1,0); return
        if key=='PageDown':
            step=getattr(self,'_scratch_page_step',21); self.scratch_idx=min(self.scratch_idx+step,total-1); return
        if key=='PageUp':
            step=getattr(self,'_scratch_page_step',21); self.scratch_idx=max(self.scratch_idx-step,0); return
        if d is not None:
            return
        if key=='Enter':
            if self.scratch_idx==0:
                self.open_input_modal('new_scratch','Enter the name of the scratchpad to open:')
            else:
                item=self.scratch_items[self.scratch_idx-1]
                self.open_scratchpad_editor(item.path)
            return
        if ch=='s':
            self.view='annual'; return
        if ch=='d':
            if self.scratch_idx>0:
                item=self.scratch_items[self.scratch_idx-1]
                self.open_confirm('delete_scratch', f'Are you sure you want to delete the scratchpad "{item.name}"?')
            return
        if ch=='r':
            if self.scratch_idx>0:
                item=self.scratch_items[self.scratch_idx-1]
                self.open_input_modal('rename_scratch', f'Enter the new name for the scratchpad "{item.name}":')
            return
    def handle_modal_event(self,ev):
        m=self.modal
        if m is None: return
        ch=ev.value if ev.kind=='char' else None
        key=ev.value if ev.kind=='key' else None
        if ev.kind=='mouse':
            self.handle_mouse_modal(ev); return
        # Input focus
        if m.get('focus')=='input':
            if key=='Tab':
                m['focus']='buttons'; return
            if key=='ShiftTab':
                m['focus']='buttons'; return
            if key=='Enter':
                self.submit_modal(); return
            if key=='Backspace':
                cur=m['cursor']
                if cur>0:
                    txt=m['input']; m['input']=txt[:cur-1]+txt[cur:]; m['cursor']=cur-1
                return
            if key=='Delete':
                cur=m['cursor']; txt=m['input']
                if cur<len(txt): m['input']=txt[:cur]+txt[cur+1:]
                return
            if key=='Left':
                m['cursor']=max(0,m['cursor']-1); return
            if key=='Right':
                m['cursor']=min(len(m['input']),m['cursor']+1); return
            if ch is not None:
                cur=m['cursor']; txt=m['input']; m['input']=txt[:cur]+ch+txt[cur:]; m['cursor']=cur+len(ch); return
            return
        else:
            # buttons focus
            btns=m.get('buttons',['Ok'])
            idx=m.get('btn_idx',0)
            d=self.translate_dir(ch,key)
            if key=='Tab':
                if 'input' in m:
                    # cycle buttons -> input if only one button? Observed password: Tab from Submit returns to input
                    if len(btns)==1:
                        m['focus']='input'
                    else:
                        # buttons cycle then input
                        if idx+1<len(btns): m['btn_idx']=idx+1
                        else: m['focus']='input'; m['btn_idx']=0
                else:
                    m['btn_idx']=(idx+1)%len(btns)
                return
            if key=='ShiftTab':
                if 'input' in m:
                    if idx>0: m['btn_idx']=idx-1
                    else: m['focus']='input'
                else:
                    m['btn_idx']=(idx-1)%len(btns)
                return
            if d=='Right':
                m['btn_idx']=min(idx+1,len(btns)-1); return
            if d=='Left':
                m['btn_idx']=max(idx-1,0); return
            if d is not None:
                return
            if key=='Enter':
                # Activate focused button
                kind=m['kind']
                if kind in ('password','new_scratch','rename_scratch'):
                    self.submit_modal(); return
                if kind=='delete_log':
                    yes=(idx==0); self.modal=None
                    if yes:
                        path=self.repo.log_path(self.selected_date)
                        if fs_exists(path) or os.path.lexists(path): fs_remove_or_throw(path)
                        self.refresh_logs(reset=True); self.preview_scroll=0
                    return
                if kind=='delete_scratch':
                    yes=(idx==0)
                    item=None
                    if self.scratch_idx>0 and self.scratch_idx-1<len(self.scratch_items): item=self.scratch_items[self.scratch_idx-1]
                    self.modal=None
                    if yes and item is not None:
                        if fs_exists(item.path) or os.path.lexists(item.path): fs_remove_or_throw(item.path)
                        self.load_scratchpads(reset=True)
                    return
                if kind=='message_ok':
                    self.modal=None; return
            return
    def submit_modal(self):
        m=self.modal; kind=m['kind']; text=m.get('input','')
        if kind=='password':
            if text=='':
                self._fatal='Password is required to open encrypted log repository!'; return
            if not self.repo.validate_password(text):
                self._fatal='Invalid password provided!'; return
            self.cfg.password=text; self.repo.encrypted=True; self.modal=None; self.phase='main'
            # ensure scratch dir after successful unlock (observed)
            scratch=self.repo.scratch_dir
            if not fs_exists(scratch): cpp_create_directories(scratch)
            self.refresh_logs/reset=True)
            if self.cfg.git.enabled:
                self.start_pull()
            return
        if kind=='new_scratch':
            self.modal=None
            if text=='':
                self.view='annual'; return
            fname=normalize_scratch_filename(text)
            path=fs_join(self.repo.scratch_dir, fname)
            self.open_scratchpad_editor(path)
            return
        if kind=='rename_scratch':
            self.modal=None
            if text=='':
                self.view='annual'; return
            if self.scratch_idx<=0: return
            item=self.scratch_items[self.scratch_idx-1]
            fname=normalize_scratch_filename(text)
            newpath=fs_join(self.repo.scratch_dir, fname)
            try:
                os.rename(item.path, newpath)
            except OSError as e:
                raise AppError(f"Failed to rename scratchpad: {os.strerror(e.errno) if e.errno else str(e)}")
            self.load_scratchpads(reset=True)
            return
    def handle_mouse(self,ev):
        # Minimal mouse support: calendar click opens editor (observed); modal buttons handled separately.
        # Mapping from screen coords to components is stored during render in self._hit_regions.
        btn,x,y,press=ev.value
        if not press:
            return
        if btn not in (0,64,65):
            return
        regions=getattr(self,'_hit_regions',[])
        for kind, x0,y0,x1,y1, data in regions:
            if x0<=x<=x1 and y0<=y<=y1:
                if btn==64 or btn==65:
                    # wheel over a menu/preview: approximate with Down/Up to that component
                    delta=1 if btn==65 else -1
                    if kind=='menu_sec': self.focus=0; self.sec_idx=max(0,min(len(self.sections)-1,self.sec_idx+delta)); self.tag_idx=0; self.recompute_menus()
                    elif kind=='menu_tag': self.focus=1; self.tag_idx=max(0,min(len(self.tags)-1,self.tag_idx+delta))
                    elif kind=='preview':
                        self.focus=3; lines=self._current_preview_lines(); self.preview_scroll=max(0,min(self.preview_scroll+delta, max(0,len(lines)-1)))
                    elif kind=='scratch_menu': self.scratch_idx=max(0,min(len(self.scratch_items),self.scratch_idx+delta))
                    return
                if kind=='cal_date':
                    dt=data
                    if dt.y==self.selected_date.y:
