                    elif kind=='menu_tag': self.focus=1; self.tag_idx=max(0,min(len(self.tags)-1,self.tag_idx+delta))
                    elif kind=='preview':
                        self.focus=3; lines=self._current_preview_lines(); self.preview_scroll=max(0,min(self.preview_scroll+delta, max(0,len(lines)-1)))
                    elif kind=='scratch_menu': self.scratch_idx=max(0,min(len(self.scratch_items),self.scratch_idx+delta))
                    return
                if kind=='cal_date':
                    dt=data
                    if dt.y==self.selected_date.y:
                        self.selected_date=dt; self.preview_scroll=0; self.focus=2; self.open_log_editor()
                    return
                if kind=='menu_sec':
                    self.focus=0
                    if data is not None and data!=self.sec_idx:
                        self.sec_idx=data; self.tag_idx=0; self.recompute_menus()
                    return
                if kind=='menu_tag':
                    self.focus=1
                    if data is not None: self.tag_idx=data
                    return
                if kind=='scratch_menu':
                    if data is not None: self.scratch_idx=data
                    return
                if kind=='preview':
                    if self.view=='annual': self.focus=3
                    return
                if kind=='calendar':
                    self.focus=2; return
        return
    def handle_mouse_modal(self,ev):
        btn,x,y,press=ev.value
        if not press or btn!=0: return
        # Buttons hit regions are stored with kind modal_button and data=index
        for kind,x0,y0,x1,y1,data in getattr(self,'_hit_regions',[]):
            if kind=='modal_button' and x0<=x<=x1 and y0<=y<=y1:
                if self.modal:
                    self.modal['btn_idx']=data; self.modal['focus']='buttons'
                    # FTXUI button activates on release; approximating with press is close enough for tests using click (press+release would double here)
                    # To avoid double, only focus on press; activation is handled in mouse release path below? Our handle_mouse_modal only gets press here.
                    # Activate immediately:
                    self.handle_modal_event(Event('key','Enter'))
                return
            if kind=='modal_input' and x0<=x<=x1 and y0<=y<=y1:
                if self.modal and 'input' in self.modal:
                    self.modal['focus']='input'
                    # cursor position approx
                    startx=data if isinstance(data,int) else x0
                    self.modal['cursor']=max(0,min(len(self.modal['input']), x-startx))
                return
    def _current_preview_lines(self):
        e=self.entries.get(self.selected_date)
        if e is None: return []
        return render_markdown(e.content, self.cfg.annual_theme.markdown)

