# ---------------- main ----------------

def main(argv=None):
    if argv is None:
        argv = sys.argv
    if 'HOME' not in os.environ:
        # Reference behaviour: getenv("HOME") is dereferenced during option setup.
        try:
            sys.stdout.buffer.flush(); sys.stderr.buffer.flush()
        except Exception:
            pass
        os.kill(os.getpid(), signal.SIGSEGV)
        return 139
    home = os.environ.get('HOME','')
    default_config = f"{home}/.caps-log/config.ini"
    try:
        cli = parse_cli(argv[1:])
        if cli.help:
            sys.stdout.write(help_text(default_config))
            return 0
        cfg = load_config(cli, default_config)
        # crypto password requirement precedes git validation (observed)
        if cli.encrypt or cli.decrypt:
            if cfg.password == '':
                if cli.encrypt:
                    raise AppError('Password must be provided when encrypting logs!')
                else:
                    raise AppError('Password must be provided when decrypting logs!')
            validate_git_config(cfg)
            sys.stdout.write('Applying crypto...\n'); sys.stdout.flush()
            apply_crypto(cfg, decrypt=(not cli.encrypt and cli.decrypt))
            return 0
        validate_git_config(cfg)
        if cfg.git.enabled:
            git_open_check(cfg)
        cpp_create_directories(cfg.log_dir)
        marker = fs_join(cfg.log_dir, '.cle')
        has_marker = fs_exists(marker)
        needs_password = False
        if cfg.password != '':
            if not has_marker:
                raise AppError('Password provided for a non encrypted repository!')
            tmp_repo = Repository(cfg)
            if not tmp_repo.validate_password(cfg.password):
                raise AppError('Invalid password provided!')
        else:
            needs_password = has_marker
        if not needs_password:
            scratch = fs_join(cfg.log_dir, 'scratchpads')
            if not fs_exists(scratch):
                cpp_create_directories(scratch)
        app = App(cfg, needs_password=needs_password)
        return app.run()
    except AppError as e:
        eprint_error(str(e))
        return 1
    except ExitApp as e:
        return e.code
    except BrokenPipeError:
        return 1
    except KeyboardInterrupt:
        return 0
    except Exception as e:
        # std::exception-like top level handler
        msg = str(e) if str(e) else type(e).__name__
        eprint_error(msg)
        return 1

if __name__ == '__main__':
    sys.exit(main())
