    editor.write_text(editor_body or f"#!/bin/sh\necho \"EDITOR:$1\" >> {base}/editor.log\nprintf '# Edited\\n' > \"$1\"\n"); editor.chmod(0o755)
    sess=base_name; tm('kill-session','-t',sess)
