import pathlib
p=pathlib.Path('caps_log.py'); t=p.read_text()
code=r'''

def cpp_std_sort(arr, comp):
    """Emulate libstdc++ std::sort (introsort) permutation, including for equal keys.
    comp(a,b) returns True if a should come before b.
    """
    n=len(arr)
    if n<=1:
        return arr
    def insertion_sort(first,last):
        if first>=last: return
        for i in range(first+1,last):
            if comp(arr[i],arr[first]):
                val=arr[i]
                # copy_backward first..i -> first+1..i+1
                arr[first+1:i+1]=arr[first:i]
                arr[first]=val
            else:
                # unguarded linear insert
                val=arr[i]; j=i
                while comp(val,arr[j-1]):
                    arr[j]=arr[j-1]; j-=1
                arr[j]=val
    def final_insertion_sort(first,last):
        if last-first>16:
            insertion_sort(first,first+16)
            for i in range(first+16,last):
                val=arr[i]; j=i
                while comp(val,arr[j-1]):
                    arr[j]=arr[j-1]; j-=1
                arr[j]=val
        else:
            insertion_sort(first,last)
    def median_to_first(result,a,b,c):
        # indices; move median of arr[a],arr[b],arr[c] to result by swapping
        if comp(arr[a],arr[b]):
            if comp(arr[b],arr[c]):
                arr[result],arr[b]=arr[b],arr[result]
            elif comp(arr[a],arr[c]):
                arr[result],arr[c]=arr[c],arr[result]
            else:
                arr[result],arr[a]=arr[a],arr[result]
        elif comp(arr[a],arr[c]):
            arr[result],arr[a]=arr[a],arr[result]
        elif comp(arr[b],arr[c]):
            arr[result],arr[c]=arr[c],arr[result]
        else:
            arr[result],arr[b]=arr[b],arr[result]
    def unguarded_partition(first,last,pivot):
        f=first; l=last
        while True:
            while comp(arr[f],pivot):
                f+=1
            l-=1
            while comp(pivot,arr[l]):
                l-=1
            if not (f<l):
                return f
            arr[f],arr[l]=arr[l],arr[f]
            f+=1
    def partition_pivot(first,last):
        mid=first+(last-first)//2
        median_to_first(first,first+1,mid,last-1)
        return unguarded_partition(first+1,last,arr[first])
    def heapsort_range(first,last):
        # Fallback (depth exhaustion): use Python sort on the subrange with a key-less comparator via functools.
        import functools
        sub=arr[first:last]
        sub.sort(key=functools.cmp_to_key(lambda a,b: -1 if comp(a,b) else (1 if comp(b,a) else 0)))
        arr[first:last]=sub
    def introsort_loop(first,last,depth):
        while last-first>16:
            if depth==0:
                heapsort_range(first,last); return
            depth-=1
            cut=partition_pivot(first,last)
            introsort_loop(cut,last,depth)
            last=cut
    import math
    depth=2*int(math.floor(math.log2(n))) if n>1 else 0
    introsort_loop(0,n,depth)
    final_insertion_sort(0,n)
    return arr
